-- Prepare editable policy drafts; never rewrite published versions or signed agreements.
INSERT INTO workplace_handbook_versions(document_id,agency_id,version_number,is_draft,changelog)
SELECT d.id,d.agency_id,COALESCE(MAX(v.version_number),0)+1,1,'Contract benefits and NLU tutoring compensation'
FROM workplace_handbook_documents d JOIN agencies a ON a.id=d.agency_id
LEFT JOIN workplace_handbook_versions v ON v.document_id=d.id
WHERE a.slug IN ('itsco','nlu','nextlevelup','nextleveluplcc','next-level-up')
GROUP BY d.id,d.agency_id
HAVING COALESCE(MAX(v.is_draft),0)=0;

INSERT INTO workplace_handbook_sections(version_id,agency_id,sort_order,slug,title,body_html,parent_slug,source_page,content_status,source_body_hash)
SELECT draft.id,s.agency_id,s.sort_order,s.slug,s.title,s.body_html,s.parent_slug,s.source_page,s.content_status,s.source_body_hash
FROM workplace_handbook_documents d JOIN agencies a ON a.id=d.agency_id JOIN workplace_handbook_versions draft ON draft.document_id=d.id AND draft.is_draft=1
JOIN workplace_handbook_sections s ON s.version_id=d.published_version_id
LEFT JOIN workplace_handbook_sections existing ON existing.version_id=draft.id
WHERE a.slug IN ('itsco','nlu','nextlevelup','nextleveluplcc','next-level-up') AND existing.id IS NULL;

INSERT INTO workplace_handbook_sections(version_id,agency_id,sort_order,slug,title,body_html,content_status)
SELECT v.id,v.agency_id,COALESCE(MAX(s.sort_order),0)+1,'nlu-tutoring-and-h2014-compensation','Tutoring and H2014 compensation','<p>Next Level Up uses the assigned compensation category and level for clinical services, indirect work and support activities. Tutoring is a separate pay type alongside Clinical Session and Direct Care rates; it does not replace the licensed employee category. This section governs the tutoring and Category 1 H2014 exceptions to the general rate schedule from the configured prospective effective date.</p>
  <table><thead><tr><th>Level</th><th>Tutoring hourly-equivalent rate</th><th>One 15-minute unit</th></tr></thead><tbody><tr><td>1</td><td>$18.00</td><td>$4.50</td></tr><tr><td>2</td><td>$20.50</td><td>$5.125</td></tr><tr><td>3</td><td>$23.00</td><td>$5.75</td></tr><tr><td>4</td><td>$25.50</td><td>$6.375</td></tr><tr><td>5</td><td>$28.00</td><td>$7.00</td></tr></tbody></table>
  <p>Tutoring compensation equals approved 15-minute units multiplied by one quarter of the assigned tutoring hourly rate. Four units equal one hour. The app generates units from actual recorded tutoring session time, retaining partial units so worked time is not discarded. Tutoring remains non-clinical and uses the internal TUTORING 15 MIN record; it is not an insurance procedure code. Older hourly tutoring records retain their original quantity basis.</p>
  <h2>Indirect allowance</h2><p>Tutoring adds 10 minutes of paid indirect time per direct-hour equivalent at the employee’s applicable indirect rate. One 15-minute unit adds 2.5 indirect minutes; four units add 10. This applies to all assigned categories. Round money after computing the full line, not each quarter-hour unit. For example, at Level 1 and an $18 indirect rate, four units earn $18 direct plus $3 indirect, totaling $21.</p>
  <h2>Category 1 H2014</h2><p>H2014 pays a $22 direct-hour-equivalent base at every Category 1 level: $5.50 per 15-minute unit. Add 10 minutes of indirect pay per direct-hour equivalent, proportionally, at the applicable indirect rate. This is an exception to Category 1’s general no-automatic-indirect rule. The $22 base also applies during probation or minimum-workload periods. Other categories and other services retain their configured rates and conditions. Service scope, approvals and payer requirements remain separate from compensation.</p>
  <h2>Session records and payroll</h2><p>Start and end the tutoring session in the app. A completed session with one assigned tutor generates separate direct-service and indirect-allowance claims for payroll review. Review actual time, units, category, level and effective rates before approval. Retrying completion does not create duplicate claims. Report missing or inaccurate session time for correction; automatic records do not replace reporting all actual compensable work. Do not submit duplicate indirect time for the allowance.</p>
  <p>Approved individual compensation terms and their effective dates control. New rates do not change compensation already earned. Clinical, tutoring, indirect and support work remain distinct in records, and benefit eligibility follows the applicable handbook and plan policies.</p>','ready'
FROM workplace_handbook_versions v JOIN agencies a ON a.id=v.agency_id
LEFT JOIN workplace_handbook_sections s ON s.version_id=v.id
WHERE v.is_draft=1 AND a.slug IN ('nlu','nextlevelup','nextleveluplcc','next-level-up')
GROUP BY v.id,v.agency_id
HAVING SUM(CASE WHEN s.slug='nlu-tutoring-and-h2014-compensation' THEN 1 ELSE 0 END)=0;

INSERT INTO workplace_handbook_sections(version_id,agency_id,sort_order,slug,title,body_html,content_status)
SELECT v.id,v.agency_id,COALESCE(MAX(s.sort_order),0)+1,'school-service-support-time','School support activity hours','<p>School-assigned employees earn a separate bank of <strong>support activity hours</strong>. All work hours and service-credit equivalents that qualify for sick-leave accrual count toward this bank while school-assigned, including eligible work outside schools. The rate is <strong>2 support activity hours per 25 qualifying hours or credits</strong>. Use the same documented qualifying basis as sick leave and count each component once. Thirty qualifying hours earn 2.4 support activity hours. The bank is separate from sick leave and Training PTO.</p><h2>Purpose — weather disruptions and missed sessions</h2><p>This earned benefit is earmarked to help school-assigned providers cover time lost to weather-related school closures or disruptions and missed client sessions, including client absences or cancellations. It is separate from sick leave and Training PTO, and is paid at the employee’s applicable support-activity rate.</p><p>Payment is limited to earned available hours and the handbook’s request and payroll-approval requirements. It is not an automatic payment for every missed appointment and does not replace wages for work actually performed. Existing earned balances and previously approved uses remain protected.</p><h2>Balance and use</h2><p>The app displays the balance as support activity hours, such as “2 support activity hours” or “10 support activity hours.” Accrual pauses at a <strong>20-hour balance cap</strong> and resumes after approved use. Track earnings by calendar year, January–December, but preserve earned unused balances rather than forfeiting them at year-end. Because use requires a date rather than a qualifying event, the applicable earned-vacation protections apply regardless of the bank’s name.</p><p>In My Payroll, choose Request support activity hours and enter the use date and number of hours. No explanation or receipt is required. Payroll checks the balance, applicable support-activity rate and payment period. Only approval and successful application to payroll deduct the hours. Pending or denied requests do not reduce the earned balance. Pay equals approved hours multiplied by the employee’s applicable support-activity hourly rate.</p><p>The app retains source periods, qualifying hours, accruals, approvals and deductions for audit. The balance will not be sent to ADP as a leave bank; payments still appear in normal payroll, tax and wage records. This benefit replaces future school Medicaid no-show compensation from its configured transition date, while preserving amounts earned under the previous policy. Do not claim both benefits for the same event.</p>','ready'
FROM workplace_handbook_versions v JOIN agencies a ON a.id=v.agency_id
LEFT JOIN workplace_handbook_sections s ON s.version_id=v.id
WHERE v.is_draft=1 AND a.slug IN ('itsco')
GROUP BY v.id,v.agency_id
HAVING SUM(CASE WHEN s.slug='school-service-support-time' THEN 1 ELSE 0 END)=0;

INSERT INTO workplace_handbook_sections(version_id,agency_id,sort_order,slug,title,body_html,content_status)
SELECT v.id,v.agency_id,COALESCE(MAX(s.sort_order),0)+1,'school-mileage-reimbursement','School mileage reimbursement','<p>While assigned to a school, I am eligible for mileage reimbursement when my travel meets the Workplace Handbook’s “School mileage reimbursement” policy. That policy determines eligible trips, reimbursement rates, documentation and submission requirements. ITSCO may change the policy prospectively with notice; changes do not remove reimbursement already earned or required by law.</p><p>Record the travel date, assigned school, originating office, eligible route and miles in My Payroll → Mileage. Use the school-travel option and the assigned office; explain any manual-distance correction. Personal commuting is not automatically an eligible business trip. The applicable handbook policy and approved claim determine reimbursable miles.</p><p>The currently saved tier rates are $0.00 per mile at Tier 1, $0.35 at Tier 2 and $0.70 at Tier 3. Payroll reviews eligibility and the applicable tier before applying reimbursement. A zero optional benefit rate does not remove any reimbursement required by law. Staff may request review of a missing route, incorrect distance or eligibility determination.</p>','ready'
FROM workplace_handbook_versions v JOIN agencies a ON a.id=v.agency_id
LEFT JOIN workplace_handbook_sections s ON s.version_id=v.id
WHERE v.is_draft=1 AND a.slug IN ('itsco')
GROUP BY v.id,v.agency_id
HAVING SUM(CASE WHEN s.slug='school-mileage-reimbursement' THEN 1 ELSE 0 END)=0;
